impl Default for MultidimensionalExpressionMetadataContent {
    fn default() -> Self {
        Self::KPIMDXMetadata(KPIMDXMetadata::default())
    }
}

impl officekit_markup_base::Read for MultidimensionalExpressionMetadataContent {
    fn other(node: Node) -> Option<Self> {
        Some(Self::Other(node))
    }

    fn read(element: &Element) -> Self {
        match officekit_markup_base::name(element) {
            Some((NS_X, "k")) => Self::KPIMDXMetadata(officekit_markup_base::read(element)),
            Some((NS_X, "p")) => {
                Self::MemberPropertyMDXMetadata(officekit_markup_base::read(element))
            }
            Some((NS_X, "ms")) => Self::SetMDXMetadata(officekit_markup_base::read(element)),
            Some((NS_X, "t")) => Self::TupleMDXMetadata(officekit_markup_base::read(element)),
            _ => Self::Other(Node::Element(element.clone())),
        }
    }
}

impl officekit_markup_base::Write for MultidimensionalExpressionMetadataContent {
    fn write_into(&self, writer: &mut officekit_markup_base::Writer<'_, '_>) {
        match self {
            Self::KPIMDXMetadata(arm) => arm.write_into(writer),
            Self::MemberPropertyMDXMetadata(arm) => arm.write_into(writer),
            Self::Other(node) => writer.other(node.clone()),
            Self::SetMDXMetadata(arm) => arm.write_into(writer),
            Self::TupleMDXMetadata(arm) => arm.write_into(writer),
        }
    }
}

